-- Example course with two lessons. Run in Supabase SQL Editor after schema.sql.
insert into public.course_content (id, data, updated_at)
values ('main', $course${"weeks":[{"id":"w1","title":"Пример недели","sub":"Два урока Python, чтобы проверить движок","days":[{"id":"l03","tag":"py","title":"Python: переменные","cards":[{"h":"Переменная — подписанная коробка","t":"Переменная хранит значение под именем. Знак <code>=</code> кладёт значение в коробку. <code>print()</code> показывает, что внутри.","code":"puls = 72\nname = \"Anna\"\nprint(name, puls)"},{"h":"Типы значений","t":"<code>int</code> — целое число (72). <code>float</code> — число с точкой (36.6). <code>str</code> — текст в кавычках (\"Anna\"). <code>bool</code> — True или False. Тип решает, что можно делать: числа складываются, а текст \"120/80\" — нет.","code":"temp = 36.6\nfieber = temp > 38.0\nprint(fieber)"}],"tasks":[{"t":"mc","q":"Что выведет программа?","code":"puls = 72\npuls = puls + 8\nprint(puls)","o":["80","72","puls + 8","Ошибку"],"a":0,"e":"Сначала в коробке 72, потом туда кладут 72 + 8."},{"t":"fill","q":"Допиши значение, чтобы программа вывела 36.6","code":"temp = ___\nprint(temp)","a":["36.6"],"e":"В Python дробная часть отделяется точкой, не запятой."},{"t":"mc","q":"Какой тип у значения 36.6?","o":["float","int","str","bool"],"a":0,"e":"Число с точкой — float."},{"t":"mc","q":"Давление записали так: rr = \"120/80\". Что это для Python?","o":["Текст (str): считать с ним нельзя","Дробь 1.5","Два числа","Ошибка"],"a":0,"e":"Кавычки делают значение текстом. Это частая проблема реальных данных: давление хранят одной строкой, и её приходится разбирать."}],"terms":[["Variable","variable","именованное место для значения"],["Datentyp","data type","тип значения: int, float, str, bool"]]},{"id":"l04","tag":"py","title":"Python: списки","cards":[{"h":"Много значений под одним именем","t":"Список хранит значения по порядку. Нумерация начинается с нуля: первый элемент — <code>[0]</code>. Индекс <code>[-1]</code> — последний.","code":"spo2 = [98, 97, 91, 95]\nprint(spo2[0])\nprint(spo2[-1])"},{"h":"Что умеет список","t":"<code>len()</code> — сколько элементов. <code>max()</code>, <code>min()</code>, <code>sum()</code> — максимум, минимум, сумма. <code>.append()</code> добавляет значение в конец.","code":"spo2 = [98, 97, 91, 95]\nspo2.append(93)\nprint(len(spo2), min(spo2))"}],"tasks":[{"t":"mc","q":"Что выведет программа?","code":"spo2 = [98, 97, 91, 95]\nprint(spo2[1])","o":["97","98","91","1"],"a":0,"e":"Счёт с нуля: [0] — это 98, [1] — это 97."},{"t":"fill","q":"Какая функция вернёт количество измерений (4)?","code":"spo2 = [98, 97, 91, 95]\nprint(___(spo2))","a":["len"],"e":"len — от слова length, длина."},{"t":"mc","q":"Чему равно spo2[-1] для списка [98, 97, 91, 95]?","o":["95","98","-1","Ошибка"],"a":0,"e":"Отрицательный индекс считает с конца. Удобно, чтобы взять последнее измерение."},{"t":"order","q":"Собери программу: создать список, добавить 110, вывести максимум","lines":["werte = [72, 80, 95]","werte.append(110)","print(max(werte))"],"e":"Python выполняет строки сверху вниз, поэтому порядок важен."}],"terms":[["Liste","list","упорядоченный набор значений"],["Index","index","номер элемента, счёт с нуля"]]}]}],"roadmap":[{"w":"Дальше","t":"Твой курс","d":"Загрузи свой JSON в course_content"}]}$course$::jsonb, now())
on conflict (id) do update set data = excluded.data, updated_at = now();
